"""Claude: group generated by Severn's ORIGINAL 20-tuple (after conjugation by P into the session chart): order via
faithful permutation action on the 756-vector closure of its roots (sympy)."""
exec(open('replay90.py').read().split("print('chain")[0])
from sympy.combinatorics import Permutation, PermutationGroup
R=[colspace(msub(I6,t))[0] for t in [mm(mm(P,m),Pi) for m in mats]]
def kk(v): return tuple(x for c in v for x in c)
Sg=[refl(v) for v in R]
assert all(refl(v)==mm(mm(P,m),Pi) for v,m in zip(R,mats))
orb={kk(v):v for v in R}; fr=list(R)
while fr:
    nw=[]
    for v in fr:
        for s in Sg:
            w=mv(s,v)
            if kk(w) not in orb: orb[kk(w)]=w; nw.append(w)
    fr=nw
units=[(Fr(1),Fr(0)),(Fr(0),Fr(1)),(Fr(-1),Fr(-1)),(Fr(-1),Fr(0)),(Fr(0),Fr(-1)),(Fr(1),Fr(1))]
allv={}
for v in orb.values():
    for u in units: w=vsc(u,v); allv[kk(w)]=w
keys=list(allv); idx={k:i for i,k in enumerate(keys)}
G=PermutationGroup([Permutation([idx[kk(mv(s,allv[k]))] for k in keys]) for s in Sg])
print('vectors:',len(keys),'; group order generated by original tuple:',G.order())
